//! Embeds the Windows application manifest.
//!
//! Release builds request administrator rights (`requireAdministrator`), debug
//! builds run as the invoking user (`asInvoker`) so automated checks do not
//! trigger a UAC prompt. The manifest is generated by `embed-manifest`, which also
//! adds per-monitor DPI awareness, long path support and Common Controls v6.

use embed_manifest::manifest::ExecutionLevel;
use embed_manifest::{embed_manifest, new_manifest};

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    if std::env::var_os("CARGO_CFG_WINDOWS").is_none() {
        return;
    }
    let level = if std::env::var("PROFILE").as_deref() == Ok("release") {
        ExecutionLevel::RequireAdministrator
    } else {
        ExecutionLevel::AsInvoker
    };
    let manifest = new_manifest("WinTweaker.App").requested_execution_level(level);
    embed_manifest(manifest).expect("cannot embed the application manifest");
}
